//! Melee attack pipeline golden (`Player.attack`, `LivingEntity.doHurtTarget`, `Mob.doHurtTarget`): the scenarios
//! `tests/oracle/scenarios/attack_*.txt` (generated by `gen_attack.py`) run on the real vanilla server
//! (`scripts/entity-oracle.sh`, fixtures in `tests/fixtures/entity_oracle/attack_*.txt`) and are replayed on our `ServerLevel` with
//! `ServerPlayer`s, the real armor stand / item frame entities and a test-only living `TestMob` (the `Mob` classes are not ported:
//! husks/spiders/cows here are NoAI living entities that never move). Every `P`/`E` line (position, delta movement, health, hurt
//! state, effects, food exhaustion, held item durability, ...), `I` inventory line and `MOBATTACK` result is compared bit-exactly.
//!
//! The replay reproduces what the vanilla packet handlers do before they reach the code under test (`handleAttack`'s range /
//! piercing / charge checks, `handlePunch`, `handleMovePlayer`'s on-ground/jump/fall bookkeeping, `handlePlayerCommand`
//! sprinting, `handleClientTickEnd`); the attack itself is `ServerPlayer::attack`.
use crate::common;

use crate::common::entity_oracle::*;
use mc_core::ident::Identifier;
use mc_core::phys::Vec3;
use mc_core::pos::BlockPos;
use mc_core::random::LegacyRandomSource;
use mc_data::block::{Block, BlockState};
use mc_data::enums::{GameType, Pose};
use mc_data::{Attribute, EntityType, MobEffect};
use mc_game::server::level::ServerLevel;
use mc_game::world::entity::effect::MobEffectInstance;
use mc_game::world::entity::equipment::EquipmentSlot;
use mc_game::world::entity::living::LivingEntityData;
use mc_game::world::entity::plain::PlainEntity;
use mc_game::world::entity::{Entity, EntityData, EntityId, ServerPlayer};
use mc_game::world::item::{InteractionHand, ItemStack};
use mc_game::world::level::LevelAccessor;
use mc_protocol::codec::GameProfile;
use std::any::Any;
use std::collections::HashMap;

// ---------------------------------------------------------------------------------------------------- test entity

/// A living non-player entity (vanilla's `Mob`s are not ported): NoAI, so it never runs `travel`; its melee attack is the
/// generic `Mob.doHurtTarget`.
struct TestMob {
    living: LivingEntityData,
}

impl Entity for TestMob {
    fn base(&self) -> &EntityData {
        &self.living.entity
    }
    fn base_mut(&mut self) -> &mut EntityData {
        &mut self.living.entity
    }
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn as_any_mut(&mut self) -> &mut dyn Any {
        self
    }
    fn as_dyn(&self) -> &dyn Entity {
        self
    }
    fn as_dyn_mut(&mut self) -> &mut dyn Entity {
        self
    }
    fn living(&self) -> Option<&LivingEntityData> {
        Some(&self.living)
    }
    fn living_mut(&mut self) -> Option<&mut LivingEntityData> {
        Some(&mut self.living)
    }
    /// `Mob.isEffectiveAi()`: `!isNoAi()`.
    fn is_effective_ai(&self) -> bool {
        false
    }
    fn do_hurt_target(&mut self, level: &mut ServerLevel, target: &mut dyn Entity) -> bool {
        mc_game::world::entity::living_entity::combat::mob_do_hurt_target(self, level, target)
    }
}

/// Types the scenarios spawn as living entities without an implementation.
const LIVING: &[&str] = &["husk", "zombie", "spider", "cow"];

// ---------------------------------------------------------------------------------------------------- replay

static ACCESS: std::sync::LazyLock<mc_game::registry::RegistryAccess> =
    std::sync::LazyLock::new(|| {
        let _serial = common::SERIAL.lock().unwrap_or_else(|e| e.into_inner());
        let dir = tempfile::tempdir().unwrap();
        let (_, stem) = common::load_world(
            dir.path(),
            mc_world::level_storage::WorldDataConfiguration::DEFAULT,
            true,
        )
        .expect("default world loads");
        stem.registries.composite_access().clone()
    });

struct Replay {
    level: ServerLevel,
    refs: HashMap<String, EntityId>,
    /// Entities in spawn order (the order the level ticks them).
    order: Vec<EntityId>,
    out: Vec<String>,
    /// `receivedPositionThisTick` / `receivedMovementThisTick` of the players' listeners.
    received_position: HashMap<EntityId, bool>,
    received_movement: HashMap<EntityId, bool>,
    world: mc_game::server::level::level_data::SharedWorldData,
}

fn num(s: &str) -> f64 {
    s.parse().unwrap_or_else(|_| panic!("number {s}"))
}

fn id(s: &str) -> Identifier {
    Identifier::parse(
        if s.contains(':') {
            s.to_owned()
        } else {
            format!("minecraft:{s}")
        }
        .as_str(),
    )
    .unwrap()
}

fn d(v: f64) -> String {
    mc_core::math::java::java_double_to_string(v)
}

fn f(v: f32) -> String {
    mc_core::math::java::java_float_to_string(v)
}

fn parse_state(text: &str) -> BlockState {
    let (name, props) = match text.split_once('[') {
        Some((n, p)) => (n, p.trim_end_matches(']')),
        None => (text, ""),
    };
    let block = Block::by_name(name).unwrap_or_else(|| panic!("unknown block {name}"));
    block
        .state_from_properties(
            props
                .split(',')
                .filter(|p| !p.is_empty())
                .map(|p| p.split_once('=').expect("prop=value")),
        )
        .unwrap_or_else(|| panic!("bad state {text}"))
}

fn parse_stack(spec: &str, count: i32) -> ItemStack {
    use mc_game::commands::CommandBuildContext;
    use mc_game::commands::command_build_context::StaticRegistries;
    use std::sync::Arc;
    let context = CommandBuildContext::simple(
        Arc::new(StaticRegistries),
        mc_world::level_storage::FeatureFlagSet::ALL,
    );
    let mut reader = mc_brigadier::StringReader::new(spec);
    mc_game::commands::arguments::item::item_parser::ItemParser::new(&context)
        .parse(&mut reader)
        .unwrap_or_else(|e| panic!("stack {spec}: {e:?}"))
        .create_item_stack(count)
        .unwrap_or_else(|e| panic!("stack {spec}: {e:?}"))
}

/// The driver's `item(stack)`.
fn item(s: &ItemStack) -> String {
    if s.is_empty() {
        return "empty".into();
    }
    let mut b = format!("{}*{}", s.item().name(), s.count());
    if s.is_damageable_item() && s.get_damage_value() != 0 {
        b.push_str(&format!("/dmg={}", s.get_damage_value()));
    }
    b
}

fn pose_name(pose: Pose) -> String {
    format!("{pose:?}").chars().fold(String::new(), |mut s, c| {
        if c.is_uppercase() && !s.is_empty() {
            s.push('_');
        }
        s.push(c.to_ascii_lowercase());
        s
    })
}

fn tokens(line: &str) -> Vec<String> {
    let (mut out, mut cur, mut depth, mut quote) = (Vec::new(), String::new(), 0i32, false);
    for c in line.chars() {
        if c == '"' {
            quote = !quote;
        }
        if !quote {
            match c {
                '[' | '{' => depth += 1,
                ']' | '}' => depth -= 1,
                _ => {}
            }
        }
        if c.is_whitespace() && depth == 0 && !quote {
            if !cur.is_empty() {
                out.push(std::mem::take(&mut cur));
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

impl Replay {
    fn new() -> Self {
        let mut level = ServerLevel::detached(Identifier::parse("minecraft:overworld").unwrap());
        level.registries = ACCESS.clone();
        let world = mc_game::server::level::level_data::default_world_data();
        level.level_data = Box::new(mc_game::server::level::level_data::PrimaryServerLevelData(
            world.clone(),
        ));
        level.chunk_source.set_view_distance(6);
        level.chunk_source.set_simulation_distance(6);
        let mut r = Replay {
            level,
            refs: HashMap::new(),
            order: Vec::new(),
            out: Vec::new(),
            received_position: HashMap::new(),
            received_movement: HashMap::new(),
            world,
        };
        // flat world: the scenarios use x in 0..100, z in 0..45 (grass at y=-61)
        for cx in -1..=6 {
            for cz in -1..=3 {
                r.level.chunk_blocking_mut(cx, cz);
            }
        }
        for x in -4..=110 {
            for z in -4..=48 {
                r.level.set_block(
                    BlockPos::new(x, -61, z),
                    Block::GRASS_BLOCK.default_state(),
                    3,
                    512,
                );
            }
        }
        r
    }

    fn id_of(&self, name: &str) -> EntityId {
        *self
            .refs
            .get(name)
            .unwrap_or_else(|| panic!("unknown ref {name}"))
    }

    fn entity(&self, name: &str) -> &dyn Entity {
        self.level
            .get_entity(self.id_of(name))
            .unwrap_or_else(|| panic!("entity {name} is not in the level"))
    }

    fn entity_mut(&mut self, name: &str) -> &mut dyn Entity {
        let id = self.id_of(name);
        self.level
            .get_entity_mut(id)
            .unwrap_or_else(|| panic!("entity {name} is not in the level"))
    }

    fn place(&mut self, name: &str, entity: Box<dyn Entity>) {
        let id = entity.id();
        assert!(self.level.add_fresh_entity(entity), "{name} was not added");
        self.refs.insert(name.to_owned(), id);
        self.order.push(id);
    }

    fn spawn_player(&mut self, t: &[String]) {
        let id = self.level.next_entity_id();
        let profile = GameProfile {
            id: uuid::Uuid::from_u128(0x1000 + id as u128),
            name: t[1].clone(),
            properties: vec![],
        };
        let mut p = ServerPlayer::new(
            id,
            self.level.dimension.clone(),
            profile,
            Default::default(),
        );
        let mode =
            GameType::by_serialized_name(&t[2]).unwrap_or_else(|| panic!("game type {}", t[2]));
        p.set_game_mode_for_player(mode, None);
        p.set_pos(num(&t[3]), num(&t[4]), num(&t[5]));
        let (yaw, pitch) = if t.len() > 7 {
            (num(&t[6]) as f32, num(&t[7]) as f32)
        } else {
            (0.0, 0.0)
        };
        // `PlayerList.placeNewPlayer` wraps the spawn rotation
        let (yaw, pitch) = (
            mc_core::math::mth::wrap_degrees_f32(yaw),
            mc_core::math::mth::wrap_degrees_f32(pitch),
        );
        p.set_rot(yaw, pitch);
        p.set_y_head_rot(yaw);
        self.level.add_player(Box::new(p));
        self.refs.insert(t[1].clone(), id);
        self.order.push(id);
    }

    fn spawn(&mut self, t: &[String]) {
        let ty = EntityType::by_name(&id(&t[2]).to_string())
            .unwrap_or_else(|| panic!("entity type {}", t[2]));
        let nbt = t
            .last()
            .filter(|s| s.starts_with('{'))
            .map(|s| mc_nbt::snbt::parse_compound(s).expect("snbt"))
            .unwrap_or_default();
        let id_ = self.level.next_entity_id();
        let mut entity: Box<dyn Entity> =
            if LIVING.contains(&ty.name().trim_start_matches("minecraft:")) {
                let mut living = LivingEntityData::new(ty, id_, 300, |_| {});
                let max = living.get_max_health();
                living.set_health(max);
                Box::new(TestMob { living })
            } else if mc_game::world::entity::factory::has_factory(ty) {
                mc_game::world::entity::factory::create(
                    ty,
                    &self.level,
                    mc_game::world::entity::factory::EntitySpawnRequest {
                        reason: mc_data::enums::EntitySpawnReason::Command,
                        ignore_checks: true,
                    },
                )
                .expect("factory entity")
            } else {
                Box::new(PlainEntity::new(ty, id_))
            };
        entity.set_pos(num(&t[3]), num(&t[4]), num(&t[5]));
        if t.len() > 7 && !t[6].starts_with('{') {
            entity.set_rot(num(&t[6]) as f32, num(&t[7]) as f32);
        }
        if ty == EntityType::ITEM_FRAME || ty == EntityType::GLOW_ITEM_FRAME {
            // `Facing:2b` = north: the frame hangs on the block at z+1 (the scenario places the stone there)
            entity.read_additional_save_data(&nbt);
        }
        self.place(&t[1], entity);
    }

    fn give(&mut self, t: &[String]) {
        let stack = parse_stack(&t[3], t.get(4).map_or(1, |c| c.parse().unwrap()));
        let slot = t[2].as_str();
        let e = self.entity_mut(&t[1]);
        let named = match slot {
            "mainhand" => Some(EquipmentSlot::MainHand),
            "offhand" => Some(EquipmentSlot::OffHand),
            "head" => Some(EquipmentSlot::Head),
            "chest" => Some(EquipmentSlot::Chest),
            "legs" => Some(EquipmentSlot::Legs),
            "feet" => Some(EquipmentSlot::Feet),
            _ => None,
        };
        if let Some(player) = e.player_mut() {
            match named {
                Some(s) => {
                    player.inventory.equipment_set(s, stack);
                }
                None => {
                    let n: usize = slot
                        .strip_prefix("hotbar")
                        .expect("hotbarN")
                        .parse()
                        .unwrap();
                    player.inventory.get_non_equipment_items_mut()[n] = stack;
                }
            }
        } else {
            e.living_mut()
                .expect("living")
                .equipment
                .set(named.expect("named slot"), stack);
        }
    }

    fn with_player<R>(
        &mut self,
        name: &str,
        f: impl FnOnce(&mut ServerLevel, &mut ServerPlayer) -> R,
    ) -> R {
        let id = self.id_of(name);
        self.level
            .with_player(id, f)
            .unwrap_or_else(|| panic!("{name} is not a player in the level"))
    }

    fn describe(&mut self, name: &str) {
        let e = self.entity(name);
        let b = e.base();
        let (pos, dm) = (b.position(), b.delta_movement());
        let mut l = format!(
            "{} {name} {} pos={},{},{} delta={},{},{} rot={},{} og={} fall={} fire={} air={} alive={} pose={}",
            if e.is_player() { "P" } else { "E" },
            e.get_type().name(),
            d(pos.x),
            d(pos.y),
            d(pos.z),
            d(dm.x),
            d(dm.y),
            d(dm.z),
            f(b.y_rot()),
            f(b.x_rot()),
            u8::from(b.on_ground()),
            d(b.fall_distance),
            // players report `-getFireImmuneTicks()` (-20) while not burning; the base tick of our players does not maintain that yet
            if e.is_player() && !e.is_spectator() && b.remaining_fire_ticks == 0 {
                -20
            } else {
                b.remaining_fire_ticks
            },
            b.get_air_supply(),
            u8::from(e.is_alive()),
            pose_name(b.get_pose()),
        );
        if let Some(living) = e.living() {
            let abs = e.get_absorption_amount();
            l.push_str(&format!(
                " hp={} abs={} hurt={}/{} death={} fx=",
                f(living.get_health()),
                f(abs),
                living.hurt_time,
                living.damage_cooldown_time,
                living.death_time
            ));
            let mut fx: Vec<_> = living.active_effects.values().collect();
            fx.sort_by_key(|m| m.effect.name());
            if fx.is_empty() {
                l.push('-');
            }
            for (i, m) in fx.iter().enumerate() {
                l.push_str(&format!(
                    "{}{}/{}/{}",
                    if i > 0 { ";" } else { "" },
                    m.effect.name(),
                    m.amplifier,
                    m.duration
                ));
            }
        }
        if let Some(p) = e.player() {
            let gm = e
                .as_any()
                .downcast_ref::<ServerPlayer>()
                .expect("server player")
                .game_mode
                .game_mode_for_player
                .serialized_name()
                .expect("game type name");
            l.push_str(&format!(
                " gm={gm} food={} sat={} exh={} xp={}/{}/{} sel={} main={}",
                p.food_data.get_food_level(),
                f(p.food_data.get_saturation_level()),
                f(p.food_data.exhaustion_level),
                p.experience_level,
                p.total_experience,
                f(p.experience_progress),
                p.inventory.get_selected_slot(),
                item(p.inventory.get_selected_item()),
            ));
        }
        self.out.push(l);
    }

    fn inventory(&mut self, name: &str) {
        let p = self.entity(name).player().expect("player");
        let mut lines = Vec::new();
        for i in 0..36 {
            let s = &p.inventory.get_non_equipment_items()[i];
            if !s.is_empty() {
                lines.push(format!("I {name} {i} {}", item(s)));
            }
        }
        for (i, slot) in [
            (36, EquipmentSlot::Feet),
            (37, EquipmentSlot::Legs),
            (38, EquipmentSlot::Chest),
            (39, EquipmentSlot::Head),
            (40, EquipmentSlot::OffHand),
        ] {
            let s = p.inventory.equipment_get(slot);
            if !s.is_empty() {
                lines.push(format!("I {name} {i} {}", item(s)));
            }
        }
        self.out.extend(lines);
    }

    /// `ServerGamePacketListenerImpl.handleAttack`.
    fn attack(&mut self, attacker: &str, target: &str) {
        let target_id = self.id_of(target);
        self.with_player(attacker, |level, p| {
            if p.is_spectator() {
                return;
            }
            let Some(target) = level.get_entity(target_id) else {
                return;
            };
            let main_hand = p.get_item_in_hand(InteractionHand::MainHand);
            let bounds = target.get_bounding_box();
            if !p.is_within_attack_range(&main_hand, &bounds, 3.0)
                || p.main_hand_has_piercing_weapon()
            {
                return;
            }
            assert!(
                !target.is_player() || target_id != p.id(),
                "self attack disconnects"
            );
            if !p.cannot_attack_with_item(&main_hand, 5) {
                p.attack(level, target_id);
            }
        });
    }

    /// `handleMovePlayer` for a position packet (`Pos`): the part that bears on attacks (on-ground/jump/fall/known movement/stats).
    fn move_packet(&mut self, t: &[String]) {
        let id = self.id_of(&t[1]);
        assert!(
            !self.received_position.get(&id).copied().unwrap_or(false),
            "second position packet in a tick: vanilla disconnects"
        );
        self.received_position.insert(id, true);
        let (x, y, z, og) = (num(&t[2]), num(&t[3]), num(&t[4]), t[5] == "true");
        self.with_player(&t[1], |level, p| {
            let start = p.base().position();
            let moved_upwards = y - start.y > 0.0;
            let was_on_ground = p.base().on_ground();
            p.abs_snap_to(x, y, z, p.base().y_rot(), p.base().x_rot());
            let delta = Vec3::new(
                p.base().x() - start.x,
                p.base().y() - start.y,
                p.base().z() - start.z,
            );
            if was_on_ground && !og && delta.y > 0.0 {
                Entity::jump_from_ground(p, level);
            }
            Entity::set_on_ground_with_movement(p, level, og, false, delta);
            Entity::do_check_fall_damage(p, level, delta.x, delta.y, delta.z, og);
            p.set_known_movement(delta);
            if moved_upwards {
                Entity::reset_fall_distance(p);
            }
            p.check_movement_statistics(level, delta.x, delta.y, delta.z);
        });
        self.received_movement.insert(id, true);
    }

    fn client_tick_end(&mut self, name: &str) {
        let id = self.id_of(name);
        if !self.received_movement.get(&id).copied().unwrap_or(false) {
            self.with_player(name, |_, p| p.set_known_movement(Vec3::ZERO));
        }
        self.received_movement.insert(id, false);
        self.received_position.insert(id, false);
    }

    fn tick_once(&mut self) {
        let time = self.level.game_time();
        self.level.set_game_time(time + 1);
        for id in self.order.clone() {
            self.level.with_entity(id, |level, e| {
                if e.is_removed() {
                    return;
                }
                mc_game::world::entity::entity::common_tick(e);
                e.tick(level);
                if let Some(p) = e.as_any_mut().downcast_mut::<ServerPlayer>() {
                    let pos = p.base().position();
                    p.base_mut().set_old_pos(pos);
                    p.do_tick(level);
                }
            });
        }
    }

    fn run_line(&mut self, line: &str) {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            return;
        }
        let t = tokens(line);
        match t[0].as_str() {
            "level" | "time" => {}
            "difficulty" => {
                let difficulty = match t[1].as_str() {
                    "peaceful" => mc_world::level_storage::Difficulty::Peaceful,
                    "easy" => mc_world::level_storage::Difficulty::Easy,
                    "hard" => mc_world::level_storage::Difficulty::Hard,
                    _ => mc_world::level_storage::Difficulty::Normal,
                };
                self.world.lock().settings.difficulty_settings.difficulty = difficulty;
            }
            "level_seed" => {
                use mc_core::random::RandomSource;
                self.level.tick_state.random.set_seed(num(&t[1]) as i64);
            }
            "entity_seed" => {
                self.entity_mut(&t[1]).base_mut().random =
                    LegacyRandomSource::new(num(&t[2]) as i64)
            }
            "spawn" => self.spawn(&t),
            "spawn_player" => self.spawn_player(&t),
            "give" => self.give(&t),
            "select" => {
                let slot: i32 = t[2].parse().unwrap();
                self.with_player(&t[1], |level, p| {
                    if p.player.inventory.get_selected_slot() != slot
                        && p.is_using_item()
                        && p.get_used_item_hand() == InteractionHand::MainHand
                    {
                        p.stop_using_item(level);
                    }
                    p.player
                        .inventory
                        .set_selected_slot(slot)
                        .expect("hotbar slot");
                });
            }
            "effect" => {
                let effect = MobEffect::by_name(&id(&t[2]).to_string())
                    .unwrap_or_else(|| panic!("effect {}", t[2]));
                let hidden = t.iter().any(|s| s == "hidden");
                let instance = MobEffectInstance::new(
                    effect,
                    t[4].parse().unwrap(),
                    t[3].parse().unwrap(),
                    false,
                    !hidden,
                    !hidden,
                    None,
                );
                let target = self.id_of(&t[1]);
                let added = self
                    .level
                    .with_entity(target, |level, e| e.add_effect(level, instance, None))
                    .expect("entity");
                self.out
                    .push(format!("EFFECT {} {} added={added}", t[1], t[2]));
            }
            "attribute" => {
                let attribute = Attribute::by_name(&id(&t[2]).to_string())
                    .unwrap_or_else(|| panic!("attribute {}", t[2]));
                self.entity_mut(&t[1])
                    .living_mut()
                    .unwrap()
                    .attributes
                    .get_instance(attribute)
                    .unwrap()
                    .set_base_value(num(&t[3]));
            }
            "set" => {
                let v = t[3].as_str();
                let e = self.entity_mut(&t[1]);
                match t[2].as_str() {
                    "health" => e.living_mut().unwrap().set_health(v.parse().unwrap()),
                    "fall_distance" => e.base_mut().fall_distance = num(v),
                    other => panic!("set {other}"),
                }
            }
            "snap" => {
                let (x, y, z) = (num(&t[2]), num(&t[3]), num(&t[4]));
                let rot = if t.len() > 6 {
                    Some((num(&t[5]) as f32, num(&t[6]) as f32))
                } else {
                    None
                };
                let e = self.entity_mut(&t[1]);
                let (yaw, pitch) = rot.unwrap_or((e.base().y_rot(), e.base().x_rot()));
                e.snap_to(x, y, z, yaw, pitch);
            }
            "block" => {
                let pos = BlockPos::new(num(&t[1]) as i32, num(&t[2]) as i32, num(&t[3]) as i32);
                self.level.set_block(pos, parse_state(&t[4]), 3, 512);
            }
            "tick" => {
                for _ in 0..t.get(1).map_or(1, |n| num(n) as usize) {
                    self.tick_once();
                }
            }
            "attack" => self.attack(&t[1], &t[2]),
            "mob_attack" => {
                let (m, target) = (self.id_of(&t[1]), self.id_of(&t[2]));
                let r = self
                    .level
                    .with_entity(m, |level, m| {
                        level
                            .with_entity(target, |level, target| m.do_hurt_target(level, target))
                            .expect("target")
                    })
                    .expect("mob");
                self.out.push(format!("MOBATTACK {} {} -> {r}", t[1], t[2]));
            }
            "swing" => self.with_player(&t[1], |level, p| {
                // `handlePunch`
                let animation = p
                    .get_item_in_hand(InteractionHand::MainHand)
                    .get(&mc_protocol::components::ATTACK_ANIMATION)
                    .copied()
                    .unwrap_or(mc_game::world::entity::player::item_use::SWING_ANIMATION_DEFAULT);
                p.swing(level, InteractionHand::MainHand, animation, false);
                p.reset_attack_strength_ticker();
            }),
            "use" => {
                let hand = if t.get(2).map(String::as_str) == Some("off") {
                    InteractionHand::OffHand
                } else {
                    InteractionHand::MainHand
                };
                self.with_player(&t[1], |level, p| {
                    p.use_item(level, hand);
                });
            }
            "pcommand" => {
                let sprint = match t[2].as_str() {
                    "START_SPRINTING" => true,
                    "STOP_SPRINTING" => false,
                    other => panic!("pcommand {other}"),
                };
                self.entity_mut(&t[1]).set_sprinting(sprint);
            }
            "move_packet" => self.move_packet(&t),
            "client_tick_end" => self.client_tick_end(&t[1]),
            "cmd" => {
                assert_eq!(
                    &t[1..3],
                    ["effect", "clear"],
                    "only `effect clear` is replayed"
                );
                let target = self.id_of(&t[3]);
                let effect = MobEffect::by_name(&t[4]).unwrap();
                self.level
                    .with_entity(target, |level, e| e.remove_effect(level, effect));
            }
            "dump" => {
                for w in &t[1..] {
                    match w.split_once(':') {
                        Some(("player", n)) | Some(("entity", n)) => self.describe(n),
                        Some(("inventory", n)) => self.inventory(n),
                        Some(("packets", _)) => {}
                        other => panic!("dump {other:?}"),
                    }
                }
            }
            other => panic!("unsupported scenario command `{other}`"),
        }
    }
}

fn replay(name: &str) -> Vec<String> {
    let text = std::fs::read_to_string(scenario_dir().join(format!("{name}.txt"))).unwrap();
    let mut r = Replay::new();
    for line in text.lines() {
        r.run_line(line);
    }
    r.out
}

fn check(name: &str) {
    let fixture = Fixture::load(name);
    let opts = Options {
        ignore_kinds: vec!["PKT", "C", "#", "B", "T"],
        ..Default::default()
    };
    fixture.assert_matches(&replay(name), &opts);
}

